import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"输入法","description":"","frontmatter":{},"headers":[],"relativePath":"software/input-method.md","filePath":"software/input-method.md","lastUpdated":1791914987000}'),n={name:"software/input-method.md"};function p(c,a,o,l,d,r){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="输入法" tabindex="-1">输入法 <a class="header-anchor" href="#输入法" aria-label="Permalink to &quot;输入法&quot;">​</a></h1><h2 id="fcitx-5" tabindex="-1">Fcitx 5 <a class="header-anchor" href="#fcitx-5" aria-label="Permalink to &quot;Fcitx 5&quot;">​</a></h2><p><a href="https://github.com/fcitx/fcitx5" target="_blank" rel="noreferrer">https://github.com/fcitx/fcitx5</a></p><p>官方仓库直接安装，主体 + 中文引擎（拼音/双拼）+ 图形配置工具</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S fcitx5 fcitx5-chinese-addons fcitx5-configtool</span></span></code></pre></div><p>GTK / Qt 程序里要能输入，还需要装对应的输入法模块</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S fcitx5-gtk fcitx5-qt</span></span></code></pre></div><h2 id="fcitx-5-配置" tabindex="-1">Fcitx 5 配置 <a class="header-anchor" href="#fcitx-5-配置" aria-label="Permalink to &quot;Fcitx 5 配置&quot;">​</a></h2><p>在 <code>~/.config/environment.d/</code> 下新建配置文件，让所有程序都能识别</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p ~/.config/environment.d</span></span></code></pre></div><p><code>~/.config/environment.d/im.conf</code> 内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GTK_IM_MODULE=fcitx</span></span>
<span class="line"><span>QT_IM_MODULE=fcitx</span></span>
<span class="line"><span>XMODIFIERS=@im=fcitx</span></span>
<span class="line"><span>SDL_IM_MODULE=fcitx</span></span></code></pre></div><p>改完注销重新登录生效。</p><h2 id="ibus" tabindex="-1">IBus <a class="header-anchor" href="#ibus" aria-label="Permalink to &quot;IBus&quot;">​</a></h2><p><a href="https://github.com/ibus/ibus" target="_blank" rel="noreferrer">https://github.com/ibus/ibus</a></p><p>另一套输入法框架，GNOME 桌面默认自带</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S ibus ibus-libpinyin</span></span></code></pre></div><h2 id="rime-中州韵" tabindex="-1">Rime（中州韵） <a class="header-anchor" href="#rime-中州韵" aria-label="Permalink to &quot;Rime（中州韵）&quot;">​</a></h2><p><a href="https://github.com/rime/home" target="_blank" rel="noreferrer">https://github.com/rime/home</a></p><p>需要自定义词库、双拼方案时用这个引擎，作为 Fcitx 5 的一个引擎运行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S fcitx5-rime</span></span></code></pre></div>`,21)])])}const b=e(n,[["render",p]]);export{u as __pageData,b as default};
